/* ---- range ---- */
/* range(start, stop, step): start inclusive, stop exclusive, step != 0. */
typedef struct { long long start; long long stop; long long step; } range_t;

/* range(stop): start = 0, step = 1 */
static inline range_t nfv_range1(long long stop) {
    range_t r; r.start = 0; r.stop = stop; r.step = 1; return r;
}

/* range(start, stop): step = 1 */
static inline range_t nfv_range2(long long start, long long stop) {
    range_t r; r.start = start; r.stop = stop; r.step = 1; return r;
}

/* range(start, stop, step); caller must ensure step != 0 (Python raises ValueError). */
static inline range_t nfv_range3(long long start, long long stop, long long step) {
    range_t r; r.start = start; r.stop = stop; r.step = step; return r;
}

/* Number of elements produced by the range (overflow-safe for |values| bounded
   so that differences fit; uses unsigned-free arithmetic via careful checks). */
static inline long long nfv_range_len(range_t r) {
    if (r.step > 0) {
        if (r.start >= r.stop) return 0;
        /* stop - start > 0; compute without overflow when both are in safe range */
        long long diff = r.stop - r.start;
        return (diff - 1) / r.step + 1;
    } else if (r.step < 0) {
        if (r.start <= r.stop) return 0;
        long long diff = r.start - r.stop;
        /* -step is safe unless step == LLONG_MIN */
        if (r.step == LLONG_MIN) return 1;
        return (diff - 1) / (-r.step) + 1;
    }
    return 0; /* step == 0 is invalid in Python */
}

/* The i-th element of the range, 0 <= i < nfv_range_len(r). */
static inline long long nfv_range_at(range_t r, long long i) {
    return r.start + i * r.step;
}

