    return rv == x + 1;
}

bool nfv_spec(list_ll l, list_ll return_value) {
    long long n = l.len;
    if (n < 0) n = 0;
    for (long long i = 0; i < n && i < NFV_MAX_LEN; i++) {
        /* return_value[i] out of range raises IndexError in Python, so the assertion fails */
        if (i >= return_value.len) return false;
        if (!nfv_spec_elem_ok(return_value.data[i], l.data[i])) return false;
